// spec: specs/admin-subscriptions.md (раздел 1.4)
// seed: tests/seed.admin.spec.ts
// Расхождения плана с живой страницей (19.11.2026):
//  - поиск срабатывает по Enter (форма), а не по вводу;
//  - в блоке подписки у «QA לייק 1» цена «—» и «נרכש» «—» (покупок нет), «אמצעי תשלום» — «אין נתוני תשלום עדיין» (как в плане).
// Предусловие данных: «QA לייק 1» — Premium выдан вручную, без покупок; если покупки появились — падение «аккаунт использован» (ОКРУЖЕНИЕ).
// Только просмотр: «הענקת …», «⋯», «כלי בדיקה» не нажимаются.
import { test, expect } from '@playwright/test';
import path from 'path';

const ADMIN_URL = 'https://magnet-admin.vercel.app';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin-r11.json') });

test.describe('Админка: «מנויים ורכישות» (#01f23b)', () => {
  test('Premium без покупок: «אין רכישות עדיין» @desktop @prod-safe', async ({ page }) => {
    await page.goto(`${ADMIN_URL}/users`);

    // 1. «מנויים ורכישות» → поиск «QA לייק 1» (U-0CBBA5) → открыть
    await page.getByRole('navigation', { name: 'ניווט ראשי' }).getByRole('link', { name: 'מנויים ורכישות' }).click();
    await expect(page).toHaveURL(/\/subscriptions$/);
    const search = page.getByRole('textbox', { name: 'חיפוש לפי שם, טלפון או מזהה' });
    await search.fill('QA לייק 1');
    await search.press('Enter');
    await expect(page).toHaveURL(/\/subscriptions\?q=/);
    const userLink = page.getByRole('link', { name: 'מנוי ורכישות של QA לייק 1' });
    await expect(userLink).toBeVisible();
    await userLink.click();
    await expect(page).toHaveURL(/\/subscriptions\/[0-9a-f-]{36}$/);

    // Заголовок и подписка Premium
    await expect(page.getByRole('heading', { level: 1, name: 'QA לייק 1' })).toBeVisible();
    await expect(page.getByText('מנוי ורכישות · U-0CBBA5')).toBeVisible();
    const sub = page.getByRole('region', { name: 'מנוי ורכישות' });
    await expect(sub.getByRole('heading', { level: 2, name: 'Magnet Premium' })).toBeVisible();

    // «רכישות (0)», в таблице «אין רכישות עדיין»
    await expect(sub.getByRole('heading', { level: 2, name: 'רכישות (0)' }), 'аккаунт использован (ОКРУЖЕНИЕ)').toBeVisible();
    await expect(sub.getByRole('cell', { name: 'אין רכישות עדיין' })).toBeVisible();

    // «אמצעי תשלום»: «אין נתוני תשלום עדיין»
    await expect(sub.getByText('אין נתוני תשלום עדיין')).toBeVisible();

    // Боковая карточка: «סה״כ הוצאה ₪0», «רכישות 0»
    const aside = page.getByRole('complementary', { name: 'פרטי הלקוח/ה' });
    await expect(aside.getByText('סה״כ הוצאה').locator('xpath=..')).toContainText('₪0');
    await expect(aside.getByText('רכישות', { exact: true }).locator('xpath=..')).toContainText(/0$/);
  });
});
